package app.runeshare;

import net.runelite.api.Item;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Turns RuneLite item containers into the item id lists the RuneShare API expects.
 * <p>
 * RuneLite reports an empty slot as -1. It is sent as null rather than as a number
 * so that the API can tell "the player left this slot empty" apart from an item it
 * failed to recognise, and so that the items after it keep their position. Trailing
 * empties are dropped, because a tab that ends early looks the same either way.
 * <p>
 * Noted items are sent under their noted item id, which the API will not recognise.
 * Unnoting them would mean an ItemComposition lookup per slot, and a combat loadout
 * rarely carries notes, so they are left alone for now.
 */
final class Loadout
{
	private static final int MAX_BACKPACK_SLOTS = 28;

	private Loadout()
	{
	}

	@Nullable
	static List<Integer> backpackItemIds(@Nullable final Item[] items)
	{
		if (items == null)
		{
			return null;
		}

		final int readableSlots = Math.min(items.length, MAX_BACKPACK_SLOTS);

		int lastFilledSlot = -1;
		for (int slot = 0; slot < readableSlots; slot++)
		{
			if (isFilled(items[slot]))
			{
				lastFilledSlot = slot;
			}
		}

		final List<Integer> itemIds = new ArrayList<>(lastFilledSlot + 1);
		for (int slot = 0; slot <= lastFilledSlot; slot++)
		{
			final Item item = items[slot];
			itemIds.add(isFilled(item) ? item.getId() : null);
		}

		return Collections.unmodifiableList(itemIds);
	}

	@Nullable
	static List<Integer> equipmentItemIds(@Nullable final Item[] items)
	{
		if (items == null)
		{
			return null;
		}

		final List<Integer> itemIds = new ArrayList<>();
		for (final Item item : items)
		{
			if (isFilled(item))
			{
				itemIds.add(item.getId());
			}
		}

		return Collections.unmodifiableList(itemIds);
	}

	/**
	 * An empty slot is -1, but 0 is treated as empty too: the API drops a 0 before it
	 * assigns positions, which would shift every later item along by one.
	 */
	private static boolean isFilled(@Nullable final Item item)
	{
		return item != null && item.getId() > 0;
	}
}

package app.runeshare;

import lombok.Value;
import net.runelite.api.WorldType;

import javax.annotation.Nullable;
import java.util.EnumSet;

/**
 * The account type and Leagues flag RuneShare shows next to a player's bank tabs and
 * task sessions.
 * <p>
 * Both come from the client (the account type varbit and the world type), which may
 * only be read on the client thread. Build one there and hand it to the EDT, rather
 * than reading the client from the code that sends it.
 */
@Value
public class PlayerAccount
{
	@Nullable
	String accountType;

	boolean leagues;

	static PlayerAccount from(final int accountTypeVarbitValue, @Nullable final EnumSet<WorldType> worldTypes)
	{
		return new PlayerAccount(accountType(accountTypeVarbitValue), isLeagues(worldTypes));
	}

	/**
	 * Returns null for a value RuneShare doesn't know, so it is left out of the request
	 * and the account type already stored on RuneShare is kept.
	 */
	@Nullable
	static String accountType(final int accountTypeVarbitValue)
	{
		switch (accountTypeVarbitValue)
		{
			case 0:
				return "normal";
			case 1:
				return "ironman";
			case 2:
				return "ultimate_ironman";
			case 3:
				return "hardcore_ironman";
			case 4:
				return "group_ironman";
			case 5:
				return "hardcore_group_ironman";
			case 6:
				return "unranked_group_ironman";
			default:
				return null;
		}
	}

	/**
	 * Deadman seasonal worlds are flagged SEASONAL too, but they are not Leagues.
	 */
	static boolean isLeagues(@Nullable final EnumSet<WorldType> worldTypes)
	{
		if (worldTypes == null)
		{
			return false;
		}

		return worldTypes.contains(WorldType.SEASONAL) && !worldTypes.contains(WorldType.DEADMAN);
	}
}

package app.runeshare;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import static app.runeshare.RuneShareConfig.CONFIG_GROUP;

@ConfigGroup(CONFIG_GROUP)
public interface RuneShareConfig extends Config
{
	String CONFIG_GROUP = "RuneShare";
	String API_TOKEN_CONFIG_KEY = "apiToken";

	@ConfigItem(
			keyName = API_TOKEN_CONFIG_KEY,
			name = "API Token",
			description = "Your unique API token for your RuneShare account. Go to https://osrs.runeshare.app/api_tokens to create one."
	)
	default String apiToken() { return null; }

	@ConfigItem(
			keyName = "autoSave",
			name = "Auto Save?",
			description = "If checked, changes to Bank Tag Tabs will automatically be saved in RuneShare."
	)
	default boolean autoSave() { return false; }

	@ConfigItem(
			keyName = "shareLocation",
			name = "Share Location?",
			description = "If checked, the world map location where a task session started will be shared with RuneShare."
	)
	default boolean shareLocation() { return true; }

	@ConfigItem(
			keyName = "shareLoadout",
			name = "Share Loadout?",
			description = "If checked, the inventory and equipment you are wearing when a task session starts will be shared with RuneShare."
	)
	default boolean shareLoadout() { return true; }
}

package app.runeshare;

import app.runeshare.api.BankTabSync;
import app.runeshare.api.ConnectionStatus;
import app.runeshare.api.RuneShareApi;
import app.runeshare.api.RuneShareBankTab;
import app.runeshare.api.RuneShareConnection;
import app.runeshare.ui.RuneSharePluginPanel;
import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.*;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

@Slf4j
@PluginDescriptor(
	name = "RuneShare",
	description = "Share bank tabs with other players",
	tags = { "gear", "inventory", "setups" }
)
@PluginDependency(BankTagsPlugin.class)
public class RuneSharePlugin extends Plugin
{
	private static final int NAVIGATION_PRIORITY = 100;
	private static final String PLUGIN_NAME = "RuneShare";
	private static final long TIME_BETWEEN_TASK_EVENTS_MS = 30 * 1000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private RuneShareConfig runeShareConfig;

	@Inject
	private TabManager tabManager;

	@Inject
	private TagManager tagManager;

	@Inject
	private BankTagsService bankTagsService;

	@Inject
	private RuneShareApi runeShareApi;

	@Inject
	private RuneShareConnection runeShareConnection;

	@Inject
	private ScheduledExecutorService scheduledExecutorService;

	private RuneSharePluginPanel panel;

	private NavigationButton navigationButton;

	private String activeTag = null;

	private Layout activeLayout = null;

	private List<Integer> activeItemIds = null;

	private RuneShareSessionTracker runeShareSessionTracker = null;

	private BankTabSync bankTabSync = null;

	private Long lastTaskEventSentAtMs = null;

	@Override
	protected void startUp() throws Exception
	{
		runeShareSessionTracker = new RuneShareSessionTracker(runeShareApi);
		bankTabSync = new BankTabSync(
				runeShareApi::sendBankTab,
				(task, delayMs) -> scheduledExecutorService.schedule(task, delayMs, TimeUnit.MILLISECONDS));

		// startUp runs on the EDT when the plugin is toggled on, but reading the
		// account type varbit asserts it is on the client thread. Returning false
		// re-queues this for the next tick, so it retries until we are logged in
		// and the varbit and world type are actually meaningful.
		clientThread.invokeLater(() -> {
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return false;
			}

			updateAccountAndWorld();
			readLoadoutFromClient();
			return true;
		});

		this.panel = new RuneSharePluginPanel(runeShareConfig, runeShareApi, runeShareConnection, runeShareSessionTracker, bankTabSync);

		checkApiToken();

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

		this.navigationButton = NavigationButton.builder()
				.tooltip(PLUGIN_NAME)
				.icon(icon)
				.priority(NAVIGATION_PRIORITY)
				.panel(this.panel)
				.build();

		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		runeShareConnection.setListener(() -> {});
		runeShareApi.cancelRetries();
		if (bankTabSync != null)
		{
			bankTabSync.cancel();
		}

		// shutDown still runs if startUp threw before the button was built.
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(RuneShareConfig.CONFIG_GROUP)) {
			if (event.getKey().equals(RuneShareConfig.API_TOKEN_CONFIG_KEY)) {
				checkApiToken();
			}

			// ConfigChanged is posted on the thread that changed the setting, the EDT for
			// the settings panel, so reading containers has to hop to the client thread.
			if (runeShareSessionTracker != null) {
				if (runeShareConfig.shareLoadout()) {
					clientThread.invokeLater(this::readLoadoutFromClient);
				} else {
					clearLoadout();
				}
			}

			final boolean shareLocation = runeShareConfig.shareLocation();
			SwingUtilities.invokeLater(() -> {
				// Coordinates are only refreshed on the next hit, so drop any that
				// were cached before the player opted out.
				if (!shareLocation) {
					this.panel.clearLocation();
				}
				this.panel.redraw();
			});
		}
	}

	@Subscribe
	public void onWorldChanged(WorldChanged event)
	{
		if (runeShareSessionTracker != null) {
			updateAccountAndWorld();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied hitsplatApplied)
	{
		Actor actor = hitsplatApplied.getActor();
		if (!(actor instanceof NPC))
		{
			return;
		}

		final Hitsplat hitsplat = hitsplatApplied.getHitsplat();
		final NPC npc = (NPC) actor;

		boolean weAreAttacking = hitsplat.isMine();
		if (weAreAttacking)
		{
			log.debug("You are attacking {}", npc.getName());

			// The ID is read here, on the client thread, because NPC.getId() turns
			// to -1 once the NPC dies or despawns, long before Start Session is clicked.
			final int npcId = npc.getId();
			final boolean npcHasNoDefinition = npcId == -1;

			// The location is best effort: the player, or their location, can be
			// absent, and the session is still worth tracking without coordinates.
			// Players can also opt out of sharing it entirely, in which case we
			// never read it in the first place.
			Integer x = null;
			Integer y = null;
			Integer plane = null;
			if (runeShareConfig.shareLocation())
			{
				final Player localPlayer = client.getLocalPlayer();
				// getWorldLocation() is in instance space inside an instance, which
				// doesn't correspond to anywhere on the real map.
				final WorldPoint playerLocation = localPlayer == null ? null : WorldPoint.fromLocalInstance(client, localPlayer.getLocalLocation());
				final WorldPoint localWorld = playerLocation == null ? null : WorldPoint.getMirrorPoint(playerLocation, true);
				x = localWorld == null ? null : localWorld.getX();
				y = localWorld == null ? null : localWorld.getY();
				plane = localWorld == null ? null : localWorld.getPlane();
			}

			if (!npcHasNoDefinition)
			{
				this.panel.updateNpc(npcId, x, y, plane);
			}

			long currentTimeInMs = System.currentTimeMillis();
			if (runeShareSessionTracker.isRunning() && (lastTaskEventSentAtMs == null || lastTaskEventSentAtMs + TIME_BETWEEN_TASK_EVENTS_MS < currentTimeInMs)) {
				final int attackXp = client.getSkillExperience(Skill.ATTACK);
				final int strengthXp = client.getSkillExperience(Skill.STRENGTH);
				final int defenceXp = client.getSkillExperience(Skill.DEFENCE);
				final int rangedXp = client.getSkillExperience(Skill.RANGED);
				final int magicXp = client.getSkillExperience(Skill.MAGIC);
				final int hitpointsXp = client.getSkillExperience(Skill.HITPOINTS);
				final int slayerXp = client.getSkillExperience(Skill.SLAYER);

				SwingUtilities.invokeLater(() -> {
					runeShareSessionTracker.updateXp(attackXp, strengthXp, defenceXp, rangedXp, magicXp, hitpointsXp, slayerXp);
				});

				lastTaskEventSentAtMs = currentTimeInMs;
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged itemContainerChanged)
	{
		if (runeShareSessionTracker == null || !runeShareConfig.shareLoadout())
		{
			return;
		}

		final int containerId = itemContainerChanged.getContainerId();
		final Item[] items = itemContainerChanged.getItemContainer().getItems();

		if (containerId == InventoryID.INV)
		{
			runeShareSessionTracker.setBackpackRunescapeItemIds(Loadout.backpackItemIds(items));
		}
		else if (containerId == InventoryID.WORN)
		{
			runeShareSessionTracker.setEquipmentRunescapeItemIds(Loadout.equipmentItemIds(items));
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (runeShareSessionTracker == null)
		{
			return;
		}

		final GameState gameState = gameStateChanged.getGameState();
		final boolean leavingCharacter = gameState == GameState.LOGIN_SCREEN || gameState == GameState.HOPPING;
		if (leavingCharacter)
		{
			clearLoadout();
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		String tag = bankTagsService.getActiveTag();

		if (tag == null) {
			if (this.activeTag != null) {
				this.activeTag = null;
				this.activeItemIds = null;
				this.activeLayout = null;

				log.debug("There is no longer an active tag");

				SwingUtilities.invokeLater(() -> {
					this.panel.updateActiveTag(null, null, null, null);
				});
			}
			return;
		}

		List<Integer> itemIds = tagManager.getItemsForTag(tag);
		Layout layout = bankTagsService.getActiveLayout();

		boolean hasTagChanged = !tag.equals(this.activeTag);
		boolean hasItemIdsChanged = activeItemIds != null && !itemIds.isEmpty() && !itemIds.equals(activeItemIds);
		boolean hasLayoutChanged = (layout != null && activeLayout == null) || (layout == null && activeLayout != null) || (layout != null && activeLayout != null && !Arrays.equals(layout.getLayout(), activeLayout.getLayout()));

		if (hasTagChanged || hasItemIdsChanged || hasLayoutChanged) {
			this.activeTag = tag;
			this.activeItemIds = new ArrayList<>(itemIds);

			if (layout != null) {
				this.activeLayout = new Layout(layout);
			} else {
				this.activeLayout = null;
			}

			log.debug("Active tag has changed to \"{}\"", this.activeTag);

			// The bank is open whenever a tag is active, so the player is logged in and
			// the account type varbit has been loaded.
			final PlayerAccount playerAccount = readPlayerAccountFromClient();

			TagTab activeTagTab = tabManager.find(this.activeTag);
			final List<Integer> itemIdsCopy = this.activeItemIds;
			final Layout layoutCopy = this.activeLayout;

			SwingUtilities.invokeLater(() -> {
				final String apiToken = runeShareConfig.apiToken();
				final boolean apiTokenUsable = apiToken != null && !apiToken.isEmpty() && runeShareConnection.getStatus() != ConnectionStatus.INVALID_TOKEN;
				if (activeTagTab != null && apiTokenUsable && runeShareConfig.autoSave()) {
					log.info("Automatically saving bank tab to RuneShare.");
					bankTabSync.sync(RuneShareBankTab.from(activeTagTab, itemIdsCopy, layoutCopy, playerAccount));
				}

				this.panel.updateActiveTag(activeTagTab, itemIdsCopy, layoutCopy, playerAccount);
			});
		}
	}

	@Provides
	RuneShareConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RuneShareConfig.class);
	}

	private void checkApiToken() {
		runeShareConnection.reset();

		final String apiToken = runeShareConfig.apiToken();
		if (apiToken != null && !apiToken.isEmpty()) {
			runeShareApi.fetchCurrentUser();
		}
	}

	/**
	 * Must run on the client thread.
	 */
	private void readLoadoutFromClient() {
		if (!runeShareConfig.shareLoadout()) {
			clearLoadout();
			return;
		}

		final ItemContainer backpack = client.getItemContainer(InventoryID.INV);
		final ItemContainer equipment = client.getItemContainer(InventoryID.WORN);

		runeShareSessionTracker.setBackpackRunescapeItemIds(backpack == null ? null : Loadout.backpackItemIds(backpack.getItems()));
		runeShareSessionTracker.setEquipmentRunescapeItemIds(equipment == null ? null : Loadout.equipmentItemIds(equipment.getItems()));
	}

	private void clearLoadout() {
		runeShareSessionTracker.setBackpackRunescapeItemIds(null);
		runeShareSessionTracker.setEquipmentRunescapeItemIds(null);
	}

	private void updateAccountAndWorld() {
		runeShareSessionTracker.setAccountType(getAccountType());
		runeShareSessionTracker.setWorldTypes(client.getWorldType());
	}

	private String getAccountType() {
		return PlayerAccount.accountType(client.getVarbitValue(Varbits.ACCOUNT_TYPE));
	}

	/**
	 * Must run on the client thread.
	 */
	private PlayerAccount readPlayerAccountFromClient() {
		return PlayerAccount.from(client.getVarbitValue(Varbits.ACCOUNT_TYPE), client.getWorldType());
	}
}

package app.runeshare;

import app.runeshare.api.*;
import lombok.Getter;
import lombok.NonNull;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.WorldType;

import javax.swing.SwingUtilities;
import java.util.EnumSet;
import java.util.List;

/**
 * Sessions are started and stopped on the EDT, and responses from RuneShare are
 * handed back to the EDT before touching the session or calling the handlers
 * passed in. {@code running} is also read by the client thread, hence volatile.
 */
@Slf4j
public class RuneShareSessionTracker {

    @NonNull
    private final RuneShareApi runeShareApi;

    @Getter
    private volatile boolean running = false;

    private Integer taskSessionId = null;

    @Setter
    private EnumSet<WorldType> worldTypes = null;

    @Setter
    private String accountType = null;

    @Setter
    private volatile List<Integer> backpackRunescapeItemIds = null;

    @Setter
    private volatile List<Integer> equipmentRunescapeItemIds = null;

    public RuneShareSessionTracker(RuneShareApi runeShareApi) {
        this.runeShareApi = runeShareApi;
    }

    public void start(final StartTaskSession startTaskSession, final StartTaskSessionResponseHandler startTaskSessionResponseHandler) {
        startTaskSession.setAccountType(accountType);
        // worldTypes is populated from the client thread, which may not have run
        // yet when a session is started, in which case this is not Leagues.
        startTaskSession.setLeagues(PlayerAccount.isLeagues(worldTypes));
        startTaskSession.setBackpackRunescapeItemIds(backpackRunescapeItemIds);
        startTaskSession.setEquipmentRunescapeItemIds(equipmentRunescapeItemIds);
        runeShareApi.startTaskSession(startTaskSession, new StartTaskSessionResponseHandler() {
            @Override
            public void onSuccess(StartTaskSessionResponse startTaskSessionResponse) {
                SwingUtilities.invokeLater(() -> {
                    running = true;
                    taskSessionId = startTaskSessionResponse.getTaskSessionId();
                    startTaskSessionResponseHandler.onSuccess(startTaskSessionResponse);
                });
            }

            @Override
            public void onFailure(String reason) {
                SwingUtilities.invokeLater(() -> startTaskSessionResponseHandler.onFailure(reason));
            }
        });
    }

    public void updateXp(int attackXp, int strengthXp, int defenceXp, int rangedXp, int magicXp, int hitpointsXp, int slayerXp) {
        if (!running) {
            return;
        }

        final RuneShareTaskEvent runeShareTaskEvent = RuneShareTaskEvent
                .builder()
                .taskSessionId(this.taskSessionId)
                .attackXp(attackXp)
                .strengthXp(strengthXp)
                .defenceXp(defenceXp)
                .rangedXp(rangedXp)
                .magicXp(magicXp)
                .hitpointsXp(hitpointsXp)
                .slayerXp(slayerXp)
                .build();

        runeShareApi.createTaskEvent(runeShareTaskEvent);
    }

    /**
     * Forgets the running session without telling RuneShare, for when the token
     * has been rejected and a stop request could never succeed.
     */
    public void abandon() {
        this.running = false;
        this.taskSessionId = null;
    }

    public void stop(StopTaskSessionResponseHandler stopTaskSessionResponseHandler) {
        this.running = false;

        final StopTaskSession stopTaskSession = StopTaskSession.builder().taskSessionId(this.taskSessionId).build();
        runeShareApi.stopTaskSession(stopTaskSession, new StopTaskSessionResponseHandler() {
            @Override
            public void onSuccess() {
                SwingUtilities.invokeLater(stopTaskSessionResponseHandler::onSuccess);
            }

            @Override
            public void onFailure(String reason) {
                SwingUtilities.invokeLater(() -> stopTaskSessionResponseHandler.onFailure(reason));
            }
        });
        this.taskSessionId = null;
    }
}

package app.runeshare.api;

import lombok.AllArgsConstructor;
import lombok.Value;

import javax.annotation.Nullable;

@Value
@AllArgsConstructor
public class ApiResponse {
    public static final int NO_RESPONSE = -1;

    private static final int HTTP_TOO_MANY_REQUESTS = 429;

    /**
     * The HTTP status, or {@link #NO_RESPONSE} when the request never got one
     * (no network, DNS failure, timeout).
     */
    int statusCode;

    @Nullable
    String body;

    /**
     * The first entry of the {@code errors} array RuneShare sends with a 422,
     * such as "Unknown NPC".
     */
    @Nullable
    String serverError;

    public ApiResponse(int statusCode, @Nullable String body) {
        this(statusCode, body, null);
    }

    public static ApiResponse noResponse() {
        return new ApiResponse(NO_RESPONSE, null);
    }

    public boolean isSuccessful() {
        return statusCode >= 200 && statusCode < 300;
    }

    public boolean isTooManyRequests() {
        return statusCode == HTTP_TOO_MANY_REQUESTS;
    }

    /**
     * Whether trying the same request again later could succeed, as opposed to
     * a response that would come back the same way every time.
     */
    public boolean isTransientFailure() {
        final boolean serverError = statusCode >= 500 && statusCode < 600;
        return statusCode == NO_RESPONSE || serverError || isTooManyRequests();
    }

    /**
     * Why the request failed, worded to finish a sentence shown to the player.
     */
    public String describeFailure() {
        if (statusCode == NO_RESPONSE) {
            return "RuneShare couldn't be reached";
        }
        if (serverError != null) {
            return serverError;
        }
        return "RuneShare responded with " + statusCode;
    }
}

package app.runeshare.api;

import lombok.Value;

import javax.annotation.Nullable;
import java.time.LocalTime;
import java.util.concurrent.Future;
import java.util.function.Consumer;

/**
 * Sends bank tabs to RuneShare, retrying transient failures, and remembers how
 * the latest one went so the panel can show it.
 * <p>
 * Only the latest tab matters: syncing a new one abandons any retry still
 * pending for the previous one. Each sync gets a generation number, and a
 * response or retry from an older generation is ignored, otherwise a slow
 * request for an old tab could report "Synced" over the newer one.
 * <p>
 * Responses arrive on OkHttp threads and retries on the scheduler's, so state is
 * guarded by this object's lock. The listener is called outside it.
 */
public class BankTabSync {
    public interface Sender {
        void send(RuneShareBankTab bankTab, Consumer<ApiResponse> onResponse);
    }

    public interface Scheduler {
        Future<?> schedule(Runnable task, long delayMs);
    }

    public enum State {
        SYNCING,
        SYNCED,
        RETRYING,
        FAILED
    }

    @Value
    public static class Status {
        State state;

        String tag;

        @Nullable
        LocalTime syncedAt;

        @Nullable
        String failure;
    }

    private final Sender sender;

    private final Scheduler scheduler;

    private Runnable listener = () -> {};

    private int generation = 0;

    @Nullable
    private Future<?> pendingRetry = null;

    @Nullable
    private Status status = null;

    public BankTabSync(Sender sender, Scheduler scheduler) {
        this.sender = sender;
        this.scheduler = scheduler;
    }

    public synchronized void setListener(final Runnable listener) {
        this.listener = listener;
    }

    /**
     * @return how the latest sync went, or null if nothing has been synced
     */
    @Nullable
    public synchronized Status getStatus() {
        return status;
    }

    public void sync(final RuneShareBankTab bankTab) {
        final int syncGeneration;
        synchronized (this) {
            cancelPendingRetry();
            syncGeneration = ++generation;
            status = new Status(State.SYNCING, bankTab.getTag(), null, null);
        }
        notifyListener();

        attempt(syncGeneration, bankTab, 1);
    }

    /**
     * Abandons any pending retry, and ignores responses still in flight.
     */
    public synchronized void cancel() {
        cancelPendingRetry();
        generation++;
    }

    private void attempt(final int syncGeneration, final RuneShareBankTab bankTab, final int attemptNumber) {
        sender.send(bankTab, response -> onResponse(syncGeneration, bankTab, attemptNumber, response));
    }

    private void onResponse(final int syncGeneration, final RuneShareBankTab bankTab, final int attemptNumber, final ApiResponse response) {
        synchronized (this) {
            if (syncGeneration != generation) {
                return;
            }

            final String tag = bankTab.getTag();
            final Long retryDelayMs = response.isSuccessful() ? null : RetryPolicy.BANK_TAB.delayBeforeRetryMs(response, attemptNumber);
            if (response.isSuccessful()) {
                status = new Status(State.SYNCED, tag, LocalTime.now(), null);
            } else if (retryDelayMs != null) {
                status = new Status(State.RETRYING, tag, null, response.describeFailure());
                pendingRetry = scheduler.schedule(() -> retry(syncGeneration, bankTab, attemptNumber + 1), retryDelayMs);
            } else {
                status = new Status(State.FAILED, tag, null, response.describeFailure());
            }
        }
        notifyListener();
    }

    private void retry(final int syncGeneration, final RuneShareBankTab bankTab, final int attemptNumber) {
        synchronized (this) {
            if (syncGeneration != generation) {
                return;
            }
            pendingRetry = null;
        }

        attempt(syncGeneration, bankTab, attemptNumber);
    }

    private void cancelPendingRetry() {
        if (pendingRetry != null) {
            pendingRetry.cancel(false);
            pendingRetry = null;
        }
    }

    private void notifyListener() {
        final Runnable listenerToNotify;
        synchronized (this) {
            listenerToNotify = listener;
        }
        listenerToNotify.run();
    }
}

package app.runeshare.api;

public enum ConnectionStatus {
    UNKNOWN,
    CONNECTED,
    INVALID_TOKEN,
    API_DISABLED,
    UNAVAILABLE;

    private static final int HTTP_UNAUTHORIZED = 401;
    private static final int HTTP_FORBIDDEN = 403;

    /**
     * The status implied by a response from any endpoint. Responses that say
     * nothing about the connection itself, such as a 404 or 422, leave it as is.
     */
    public ConnectionStatus after(final ApiResponse response) {
        if (response.isSuccessful()) {
            return CONNECTED;
        }

        switch (response.getStatusCode()) {
            case HTTP_UNAUTHORIZED:
                return INVALID_TOKEN;
            case HTTP_FORBIDDEN:
                return API_DISABLED;
            default:
                return response.isTransientFailure() ? UNAVAILABLE : this;
        }
    }
}

