package app.runeshare.api;

import org.junit.Before;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class BankTabSyncTest
{
	private static class SentRequest
	{
		final String tag;
		final Consumer<ApiResponse> respond;

		SentRequest(String tag, Consumer<ApiResponse> respond)
		{
			this.tag = tag;
			this.respond = respond;
		}
	}

	private static class ScheduledRetry
	{
		final Runnable task;
		final long delayMs;
		final CompletableFuture<Void> future = new CompletableFuture<>();

		ScheduledRetry(Runnable task, long delayMs)
		{
			this.task = task;
			this.delayMs = delayMs;
		}
	}

	private final List<SentRequest> sent = new ArrayList<>();
	private final List<ScheduledRetry> scheduled = new ArrayList<>();
	private BankTabSync bankTabSync;

	@Before
	public void setUp()
	{
		bankTabSync = new BankTabSync(
				(bankTab, respond) -> sent.add(new SentRequest(bankTab.getTag(), respond)),
				(task, delayMs) -> {
					final ScheduledRetry retry = new ScheduledRetry(task, delayMs);
					scheduled.add(retry);
					return retry.future;
				});
	}

	@Test
	public void showsSyncingUntilRuneShareAnswers()
	{
		bankTabSync.sync(bankTab("Barrows"));

		assertEquals(BankTabSync.State.SYNCING, bankTabSync.getStatus().getState());
	}

	@Test
	public void showsWhenItSynced()
	{
		bankTabSync.sync(bankTab("Barrows"));
		sent.get(0).respond.accept(response(201));

		assertEquals(BankTabSync.State.SYNCED, bankTabSync.getStatus().getState());
		assertNotNull(bankTabSync.getStatus().getSyncedAt());
	}

	@Test
	public void retriesATransientFailureUntilItSucceeds()
	{
		bankTabSync.sync(bankTab("Barrows"));
		sent.get(0).respond.accept(ApiResponse.noResponse());

		assertEquals(BankTabSync.State.RETRYING, bankTabSync.getStatus().getState());
		assertEquals(30_000, scheduled.get(0).delayMs);

		scheduled.get(0).task.run();
		sent.get(1).respond.accept(response(201));

		assertEquals(2, sent.size());
		assertEquals(BankTabSync.State.SYNCED, bankTabSync.getStatus().getState());
	}

	@Test
	public void givesUpAfterThreeRetries()
	{
		bankTabSync.sync(bankTab("Barrows"));
		for (int attempt = 0; attempt < 3; attempt++)
		{
			sent.get(attempt).respond.accept(response(503));
			scheduled.get(attempt).task.run();
		}
		sent.get(3).respond.accept(response(503));

		assertEquals(3, scheduled.size());
		assertEquals(BankTabSync.State.FAILED, bankTabSync.getStatus().getState());
	}

	@Test
	public void showsTheServersReasonForARejectedTab()
	{
		bankTabSync.sync(bankTab("Barrows"));
		sent.get(0).respond.accept(new ApiResponse(422, null, "Tag is too long"));

		assertEquals(BankTabSync.State.FAILED, bankTabSync.getStatus().getState());
		assertEquals("Tag is too long", bankTabSync.getStatus().getFailure());
		assertTrue(scheduled.isEmpty());
	}

	@Test
	public void aNewerTabReplacesAPendingRetry()
	{
		bankTabSync.sync(bankTab("Barrows"));
		sent.get(0).respond.accept(ApiResponse.noResponse());

		bankTabSync.sync(bankTab("Zulrah"));

		assertTrue(scheduled.get(0).future.isCancelled());

		scheduled.get(0).task.run();

		assertEquals(2, sent.size());
		assertEquals("Zulrah", sent.get(1).tag);
	}

	@Test
	public void aLateResponseForAnOlderTabIsIgnored()
	{
		bankTabSync.sync(bankTab("Barrows"));
		bankTabSync.sync(bankTab("Zulrah"));
		sent.get(1).respond.accept(response(201));

		sent.get(0).respond.accept(ApiResponse.noResponse());

		assertEquals("Zulrah", bankTabSync.getStatus().getTag());
		assertEquals(BankTabSync.State.SYNCED, bankTabSync.getStatus().getState());
		assertTrue(scheduled.isEmpty());
	}

	@Test
	public void cancelStopsPendingRetries()
	{
		bankTabSync.sync(bankTab("Barrows"));
		sent.get(0).respond.accept(ApiResponse.noResponse());

		bankTabSync.cancel();
		scheduled.get(0).task.run();

		assertTrue(scheduled.get(0).future.isCancelled());
		assertEquals(1, sent.size());
	}

	private static RuneShareBankTab bankTab(String tag)
	{
		final RuneShareBankTab bankTab = new RuneShareBankTab();
		bankTab.setTag(tag);
		return bankTab;
	}

	private static ApiResponse response(int statusCode)
	{
		return new ApiResponse(statusCode, null);
	}
}

package app.runeshare.api;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class RetryPolicyTest
{
	@Test
	public void bankTabBacksOffThenGivesUp()
	{
		final ApiResponse unreachable = ApiResponse.noResponse();

		assertEquals(Long.valueOf(30_000), RetryPolicy.BANK_TAB.delayBeforeRetryMs(unreachable, 1));
		assertEquals(Long.valueOf(60_000), RetryPolicy.BANK_TAB.delayBeforeRetryMs(unreachable, 2));
		assertEquals(Long.valueOf(120_000), RetryPolicy.BANK_TAB.delayBeforeRetryMs(unreachable, 3));
		assertNull(RetryPolicy.BANK_TAB.delayBeforeRetryMs(unreachable, 4));
	}

	@Test
	public void bankTabRetriesServerErrorsAndRateLimits()
	{
		assertEquals(Long.valueOf(30_000), RetryPolicy.BANK_TAB.delayBeforeRetryMs(response(503), 1));
		assertEquals(Long.valueOf(30_000), RetryPolicy.BANK_TAB.delayBeforeRetryMs(response(429), 1));
	}

	@Test
	public void neverRetriesResponsesThatWouldRepeat()
	{
		for (int statusCode : new int[] { 401, 403, 404, 422 })
		{
			assertNull("status " + statusCode, RetryPolicy.BANK_TAB.delayBeforeRetryMs(response(statusCode), 1));
			assertNull("status " + statusCode, RetryPolicy.STOP_TASK_SESSION.delayBeforeRetryMs(response(statusCode), 1));
		}
	}

	@Test
	public void stopTaskSessionMakesThreeAttempts()
	{
		final ApiResponse serverError = response(500);

		assertEquals(Long.valueOf(5_000), RetryPolicy.STOP_TASK_SESSION.delayBeforeRetryMs(serverError, 1));
		assertEquals(Long.valueOf(5_000), RetryPolicy.STOP_TASK_SESSION.delayBeforeRetryMs(serverError, 2));
		assertNull(RetryPolicy.STOP_TASK_SESSION.delayBeforeRetryMs(serverError, 3));
	}

	@Test
	public void stopTaskSessionDoesNotRetryRateLimits()
	{
		assertNull(RetryPolicy.STOP_TASK_SESSION.delayBeforeRetryMs(response(429), 1));
	}

	private static ApiResponse response(int statusCode)
	{
		return new ApiResponse(statusCode, null);
	}
}

package app.runeshare.api;

import app.runeshare.RuneShareConfig;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class RuneShareConnectionTest
{
	private static final String TOKEN = "current-token";

	private static final CurrentUser MIKE = new CurrentUser("mike", "osrs", new CurrentUser.ApiToken("RuneLite"), null);

	private String configuredToken;
	private int notifications;
	private RuneShareConnection connection;

	@Before
	public void setUp()
	{
		configuredToken = TOKEN;
		notifications = 0;
		connection = new RuneShareConnection(new RuneShareConfig()
		{
			@Override
			public String apiToken()
			{
				return configuredToken;
			}
		});
		connection.setListener(() -> notifications++);
	}

	@Test
	public void startsUnknown()
	{
		assertEquals(ConnectionStatus.UNKNOWN, connection.getStatus());
	}

	@Test
	public void successConnects()
	{
		connection.report(TOKEN, response(201));

		assertEquals(ConnectionStatus.CONNECTED, connection.getStatus());
	}

	@Test
	public void unauthorizedFromAnyEndpointInvalidatesTheToken()
	{
		connection.report(TOKEN, response(200));
		connection.report(TOKEN, response(401));

		assertEquals(ConnectionStatus.INVALID_TOKEN, connection.getStatus());
	}

	@Test
	public void forbiddenMeansTheApiIsDisabled()
	{
		connection.report(TOKEN, response(403));

		assertEquals(ConnectionStatus.API_DISABLED, connection.getStatus());
	}

	@Test
	public void transientFailuresMakeItUnavailable()
	{
		for (int statusCode : new int[] { ApiResponse.NO_RESPONSE, 429, 500, 503 })
		{
			connection.reset();
			connection.report(TOKEN, response(statusCode));

			assertEquals("status " + statusCode, ConnectionStatus.UNAVAILABLE, connection.getStatus());
		}
	}

	@Test
	public void successRecoversFromUnavailable()
	{
		connection.report(TOKEN, ApiResponse.noResponse());
		connection.report(TOKEN, response(201));

		assertEquals(ConnectionStatus.CONNECTED, connection.getStatus());
	}

	@Test
	public void requestErrorsLeaveTheStatusAlone()
	{
		connection.report(TOKEN, response(200));
		connection.report(TOKEN, response(404));
		connection.report(TOKEN, response(422));

		assertEquals(ConnectionStatus.CONNECTED, connection.getStatus());
	}

	@Test
	public void ignoresResponsesForAReplacedToken()
	{
		connection.report(TOKEN, response(200));
		configuredToken = "new-token";
		connection.reset();

		connection.report(TOKEN, response(401));

		assertEquals(ConnectionStatus.UNKNOWN, connection.getStatus());
	}

	@Test
	public void ignoresTheCurrentUserForAReplacedToken()
	{
		configuredToken = "new-token";

		connection.reportCurrentUser(TOKEN, response(200), MIKE);

		assertNull(connection.getCurrentUser());
	}

	@Test
	public void remembersTheCurrentUserUntilReset()
	{
		connection.reportCurrentUser(TOKEN, response(200), MIKE);
		connection.report(TOKEN, response(201));

		assertEquals(MIKE, connection.getCurrentUser());

		connection.reset();

		assertNull(connection.getCurrentUser());
		assertEquals(ConnectionStatus.UNKNOWN, connection.getStatus());
	}

	@Test
	public void notifiesOnlyWhenSomethingChanges()
	{
		connection.report(TOKEN, response(201));
		connection.report(TOKEN, response(201));
		connection.reportCurrentUser(TOKEN, response(200), MIKE);
		connection.reportCurrentUser(TOKEN, response(200), MIKE);

		assertEquals(2, notifications);
	}

	private static ApiResponse response(int statusCode)
	{
		return new ApiResponse(statusCode, null);
	}
}
